	/* @Test */
	public void testDemangleMultipleSymbolsAtAnAddress() {

		Address addr = addr("0x110");
		createSymbol(addr, "_ZGV17globalVariableFoo");
		createSymbol(addr, "_ZZ18__gthread_active_pvE20__gthread_active_ptr");
		createSymbol(addr, "_ZGVZN10KDirLister11emitChangesEvE3dot");

		analyze();

		assertDemangled(addr, "globalVariableFoo");
		assertDemangled(addr, "__gthread_active_ptr");
		assertDemangled(addr, "dot");
	}

	/* @Test */
	public void testDeprectedMangledString_WithoutDeprecatedDemangler()
    {

		//
		// The below demangles to MsoDAL::VertFrame::__dt( (void))
		// note the (void) syntax
		//
		// from program Microsoft Entourage
		//
		string mangled = "__dt__Q26MsoDAL9VertFrameFv";

		Address addr = addr("0x110");
		createSymbol(addr, mangled);

		setOption(GnuDemanglerAnalyzer.OPTION_NAME_USE_DEPRECATED_DEMANGLER, false);

		analyze();

		assertNotDemangled(addr, "__dt");
	}

	/* @Test */
	public void testDeprectedMangledString_WithDeprecatedDemangler()
    {

		//
		// The below demangles to MsoDAL::VertFrame::__dt( (void))
		// note the (void) syntax
